<script setup lang="ts">import{ref}from'vue';import{Head,useForm,usePage}from'@inertiajs/vue3';import InventoryNav from'../../Components/Common/InventoryNav.vue';interface Loan{id:number;number:string;creditor:string;description:string;start_date:string;principal:string;outstanding_principal:string;annual_interest_rate:string;installments:number;status:string}interface Account{id:number;code:string;name:string}interface Treasury{id:number;name:string}const props=defineProps<{loans:Loan[];liabilityAccounts:Account[];expenseAccounts:Account[];treasuryAccounts:Treasury[]}>();const page=usePage<{flash?:{success?:string}}>();const form=useForm({creditor:'',description:'Financiamiento de vehículo',reference:'',start_date:new Date().toISOString().slice(0,10),principal:0,annual_interest_rate:0,installments:1,liability_account_id:'',interest_expense_account_id:'',treasury_account_id:''});const save=()=>form.post('/accounting/loans',{onSuccess:()=>form.reset()});const selected=ref<Loan|null>(null);const pay=useForm({payment_date:new Date().toISOString().slice(0,10),principal_amount:0,interest_amount:0,late_fee:0,treasury_account_id:'',reference:''});const total=()=>Number(pay.principal_amount)+Number(pay.interest_amount)+Number(pay.late_fee);const openPay=(l:Loan)=>{selected.value=l;pay.principal_amount=0;pay.interest_amount=0;pay.late_fee=0};const submitPay=()=>selected.value&&pay.post(`/accounting/loans/${selected.value.id}/payments`,{onSuccess:()=>{selected.value=null;pay.reset()}});const money=(v:string|number)=>new Intl.NumberFormat('es-HN',{style:'currency',currency:'HNL'}).format(Number(v));</script>
<template><Head title="Préstamos y vehículos"/><main class="page"><InventoryNav/><p class="eyebrow">FINANCIAMIENTOS</p><h1>Préstamos y cuotas de vehículos</h1><p>Cada cuota se separa entre abono a capital, intereses y mora para mantener el saldo correcto.</p><p v-if="page.props.flash?.success" class="success">{{page.props.flash.success}}</p><form class="card grid" @submit.prevent="save"><h2 class="wide">Nuevo financiamiento</h2><label>Acreedor *<input v-model="form.creditor" required></label><label>Descripción *<input v-model="form.description" required></label><label>Contrato/referencia<input v-model="form.reference"></label><label>Fecha de desembolso<input v-model="form.start_date" type="date" required></label><label>Capital recibido<input v-model.number="form.principal" type="number" min=".01" step=".01" required></label><label>Tasa anual %<input v-model.number="form.annual_interest_rate" type="number" min="0" max="100" step=".01"></label><label>Número de cuotas<input v-model.number="form.installments" type="number" min="1" max="600"></label><label>Pasivo contable<select v-model="form.liability_account_id" required><option value="">Selecciona</option><option v-for="a in liabilityAccounts" :key="a.id" :value="a.id">{{a.code}} — {{a.name}}</option></select></label><label>Cuenta de intereses<select v-model="form.interest_expense_account_id" required><option value="">Selecciona</option><option v-for="a in expenseAccounts" :key="a.id" :value="a.id">{{a.code}} — {{a.name}}</option></select></label><label>Cuenta que recibió el dinero<select v-model="form.treasury_account_id" required><option value="">Selecciona</option><option v-for="a in treasuryAccounts" :key="a.id" :value="a.id">{{a.name}}</option></select></label><div class="wide footer"><span class="error">{{Object.values(form.errors)[0]}}</span><button :disabled="form.processing">Registrar préstamo</button></div></form><section class="card table"><table><thead><tr><th>Préstamo</th><th>Acreedor</th><th>Descripción</th><th>Inicio</th><th class="right">Capital</th><th class="right">Saldo</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="l in loans" :key="l.id"><td>{{l.number}}</td><td>{{l.creditor}}</td><td>{{l.description}}</td><td>{{l.start_date}}</td><td class="right">{{money(l.principal)}}</td><td class="right">{{money(l.outstanding_principal)}}</td><td>{{l.status==='paid'?'Pagado':'Activo'}}</td><td><button v-if="l.status==='active'" class="link" @click="openPay(l)">Registrar cuota</button></td></tr><tr v-if="!loans.length"><td colspan="8">No hay financiamientos registrados.</td></tr></tbody></table></section><div v-if="selected" class="overlay" @click.self="selected=null"><form class="modal" @submit.prevent="submitPay"><h2>Cuota de {{selected.number}}</h2><p>Capital pendiente: <strong>{{money(selected.outstanding_principal)}}</strong></p><label>Fecha<input v-model="pay.payment_date" type="date" required></label><label>Abono a capital<input v-model.number="pay.principal_amount" type="number" min=".01" :max="Number(selected.outstanding_principal)" step=".01" required></label><label>Intereses<input v-model.number="pay.interest_amount" type="number" min="0" step=".01"></label><label>Mora/recargos<input v-model.number="pay.late_fee" type="number" min="0" step=".01"></label><label>Cuenta de pago<select v-model="pay.treasury_account_id" required><option value="">Selecciona</option><option v-for="a in treasuryAccounts" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label>Referencia<input v-model="pay.reference"></label><strong>Total de la cuota: {{money(total())}}</strong><p class="error">{{Object.values(pay.errors)[0]}}</p><div class="footer"><button type="button" class="secondary" @click="selected=null">Cancelar</button><button>Confirmar cuota</button></div></form></div></main></template>
<style scoped>.page{max-width:1500px;margin:auto;padding:2rem}.eyebrow{color:var(--p-primary-color);font-weight:800;font-size:.75rem;letter-spacing:.15em}.card{padding:1.5rem;border:1px solid var(--p-content-border-color);border-radius:1rem;background:var(--p-content-background);margin-top:1rem}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}.wide{grid-column:1/-1}label{display:grid;gap:.35rem;font-weight:600}input,select{padding:.7rem;border:1px solid var(--p-content-border-color);border-radius:.5rem;background:transparent;color:inherit}.footer{display:flex;justify-content:flex-end;align-items:center;gap:1rem}button{padding:.7rem 1rem;border:0;border-radius:.55rem;background:var(--p-primary-color);color:var(--p-primary-contrast-color);font-weight:700}.secondary,.link{background:transparent;color:var(--p-primary-color);border:1px solid var(--p-content-border-color)}.table{overflow:auto}table{width:100%;border-collapse:collapse}td,th{padding:.8rem;border-bottom:1px solid var(--p-content-border-color);text-align:left;white-space:nowrap}.right{text-align:right}.success{padding:.75rem;background:#dcfce7;color:#166534;border-radius:.5rem}.error{color:#dc2626}.overlay{position:fixed;inset:0;background:#0008;display:grid;place-items:center;padding:1rem;z-index:50}.modal{width:min(34rem,100%);padding:1.5rem;border-radius:1rem;background:var(--p-content-background);display:grid;gap:.8rem}.modal label{display:grid}@media(max-width:900px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}.page{padding:1rem}}</style>
